/// Loads server configuration and serves HTTP on port 6999.
///
/// Initializes a process-wide subscriber after loading dotenv. Embedded hosts
/// with their own subscriber should call [`serve_exposed`] instead.
///
/// # Errors
/// Returns an error if subscriber setup, configuration, runtime creation, or
/// server startup fails.
pub fn run_server() -> anyhow::Result<()> {
    dotenvy::dotenv().ok();
    super::tracing::init_subscriber()?;
    let config = ServerConfig::from_env().context("reading HTTP server configuration")?;

    tokio::runtime::Runtime::new()
        .context("creating HTTP server runtime")?
        .block_on(async {
            let listener = TcpListener::bind("0.0.0.0:6999")
                .await
                .context("binding HTTP server port 6999")?;
            serve_exposed(&config, listener).await
        })
}

/// Starts an `exposed` HTTP server
///
/// # Errors
/// Returns an error if connecting to the database or serving HTTP fails.
pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string)
        .await
        .context("connecting HTTP server database")?;
    let service = EntitySearchService::new(db.clone(), db.clone());

    let state = AppState {
        entity_search_service: Arc::new(service),
        entity_details_service: Arc::new(crate::domain::services::entity_details::Service::new(db)),
    };
    let router = routes().with_state(state);

    tracing::info!(address = %listener.local_addr()?, "HTTP server listening");
    axum::serve(listener, router)
        .await
        .context("serving HTTP requests")?;

    Ok(())
}
import { test as base, expect } from "@playwright/test";
import { createServer, type ServerResponse } from "node:http";
import { spawn } from "node:child_process";
import { once } from "node:events";

type Reply = {
  status?: number;
  body?: string;
  json?: unknown;
  contentType?: string;
};
type BackendRoute = {
  request(): { url(): string };
  fulfill(reply: Reply): Promise<void>;
};
export class Backend {
  handlers: { pattern: string; handle: (route: BackendRoute) => unknown }[] =
    [];
  waiters: {
    predicate: (request: { url(): string }) => boolean;
    resolve: () => void;
  }[] = [];
  async route(pattern: string, handle: (route: BackendRoute) => unknown) {
    this.handlers.push({ pattern, handle });
  }
  async unroute(pattern: string) {
    this.handlers = this.handlers.filter(
      (handler) => handler.pattern !== pattern,
    );
  }
  waitForRequest(predicate: (request: { url(): string }) => boolean) {
    return new Promise<void>((resolve) =>
      this.waiters.push({ predicate, resolve }),
    );
  }
  async respond(url: string, response: ServerResponse) {
    const request = { url: () => url };
    for (const waiter of this.waiters)
      if (waiter.predicate(request)) waiter.resolve();
    const handler = this.handlers.findLast(({ pattern }) =>
      new RegExp(
        "^" +
          pattern
            .split("*")
            .map((part) => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
            .join(".*") +
          "$",
      ).test(url),
    );
    if (!handler) {
      response.writeHead(404).end();
      return;
    }
    await handler.handle({
      request: () => request,
      fulfill: async ({ status = 200, body, json, contentType }) => {
        response.writeHead(status, {
          "content-type":
            contentType ??
            (json === undefined ? "text/plain" : "application/json"),
        });
        response.end(json === undefined ? body : JSON.stringify(json));
      },
    });
  }
}
export const test = base.extend<
  { backend: Backend },
  {
    analytics: boolean;
    development: boolean;
    application: { url: string; backend: Backend };
  }
>({
  analytics: [false, { option: true, scope: "worker" }],
