//! Current-term rankings retain exact totals and distinct entity identities.
use super::{entity_details::{DeclaredGbpPeriodTotal, MemberDeclaration}, funder::{FunderId, FunderKind}, parliament_member::MemberId};

/// Minimal member identity in a ranking.
#[derive(Clone, Debug)]
pub struct RankedMember { pub id: MemberId, pub name: String }
/// Canonical funder identity and classification.
#[derive(Clone, Debug)]
pub struct RankedFunder { pub id: FunderId, pub name: String, pub kind: FunderKind }
/// Recipient's latest party identity.
#[derive(Clone, Debug)]
pub struct RankedParty { pub id: i32, pub name: String }
/// A ranked identity and its backend-owned financial total.
#[derive(Debug)]
pub struct Ranking<I> { pub identity: I, pub total: DeclaredGbpPeriodTotal }
/// Four top-ten boards from one current-term snapshot.
#[derive(Debug)]
pub struct Rankings {
    pub current_term_start: chrono::DateTime<chrono::Utc>,
    pub members: Vec<Ranking<RankedMember>>,
    pub individuals: Vec<Ranking<RankedFunder>>,
    pub companies: Vec<Ranking<RankedFunder>>,
    pub parties: Vec<Ranking<RankedParty>>,
}
/// One declaration with canonical funder identities for its funding entries.
pub struct RankingDeclaration {
    pub member: RankedMember,
    pub party: RankedParty,
    pub declaration: MemberDeclaration,
    pub funders: Vec<Option<RankedFunder>>,
}
//! Exact current-term rankings use the same aggregate as member summaries.
use crate::domain::{models::{declared_totals::{CurrentParliamentStart, PeriodAggregate}, entity_details::DeclarationCategory, funder::FunderKind, rankings::*}, repositories::rankings::{RankingsError, RankingsRepo}};
use std::collections::BTreeMap;
/// Fixed current-term top-ten operation.
pub trait RankingsService: Clone + Send + Sync + 'static {
    /// Returns all four boards from one snapshot.
    fn rankings(&self) -> impl Future<Output = Result<Rankings, RankingsError>> + Send;
}
/// Rankings application service.
#[derive(Clone)]
pub struct Service<R> { repo: R }
impl<R> Service<R> {
    /// Creates a rankings service.
    pub const fn new(repo: R) -> Self { Self { repo } }
}
fn top<K: Ord, I>(groups: BTreeMap<K, (I, PeriodAggregate)>) -> Vec<Ranking<I>> {
    let mut rows: Vec<_> = groups.into_iter().map(|(key, (identity, aggregate))| (key, Ranking { identity, total: aggregate.gbp_total() })).collect();
    rows.sort_by(|left, right| right.1.total.amount.cmp(&left.1.total.amount).then_with(|| left.0.cmp(&right.0)));
    rows.into_iter().take(10).map(|(_, row)| row).collect()
}
impl<R: RankingsRepo> RankingsService for Service<R> {
    async fn rankings(&self) -> Result<Rankings, RankingsError> {
        let boundary = CurrentParliamentStart::new();
        let sources = self.repo.ranking_declarations(boundary.value()).await?;
        Ok(summarize(sources, boundary))
    }
}
fn summarize(sources: Vec<RankingDeclaration>, boundary: CurrentParliamentStart) -> Rankings {
    let mut members = BTreeMap::new();
    let mut individuals = BTreeMap::new();
    let mut companies = BTreeMap::new();
    let mut parties = BTreeMap::new();
    for source in sources {
        let declaration = source.declaration;
        if !boundary.includes(&declaration) { continue; }
        members.entry(source.member.id.value()).or_insert_with(|| (source.member, PeriodAggregate::default())).1.observe(&declaration);
        if declaration.category != DeclarationCategory::DonationSupport { continue; }
        let party = parties.entry(source.party.id).or_insert_with(|| (source.party.clone(), PeriodAggregate::default()));
        // Stored party labels may differ; identity remains the party ID.
        if source.party.name < party.0.name { party.0.name = source.party.name; }
        party.1.observe(&declaration);
        let mut funders = BTreeMap::new();
        for (entry, funder) in declaration.entries.iter().zip(source.funders) {
            if let Some(funder) = funder {
                funders.entry(funder.id.value()).or_insert_with(|| (funder, Vec::new())).1.push(entry.clone());
            }
        }
        for (key, (funder, entries)) in funders {
            let board = match funder.kind {
                FunderKind::Individual => &mut individuals,
                FunderKind::Company => &mut companies,
                FunderKind::Trust | FunderKind::TradeUnion | FunderKind::Other | FunderKind::NotSpecified | FunderKind::BuildingSociety | FunderKind::LimitedLiabilityPartnership | FunderKind::UnincorporatedAssociation | FunderKind::FriendlySociety | FunderKind::RegisteredParty => continue,
            };
            let mut projected = declaration.clone();
            projected.entries = entries;
            board.entry(key).or_insert_with(|| (funder, PeriodAggregate::default())).1.observe(&projected);
        }
    }
    Rankings { current_term_start: boundary.value(), members: top(members), individuals: top(individuals), companies: top(companies), parties: top(parties) }
}
use crate::{domain::{models::{entity_details::{DeclarationCategory, DeclaredFunding, MemberDeclaration}, funder::{FunderId, FunderKind}, rankings::*}, repositories::rankings::{RankingsError, RankingsRepo}}, outbound::ExposedDatabase};
use super::currency::CURRENCY_WHITESPACE;
use std::str::FromStr;

impl RankingsRepo for ExposedDatabase {
    async fn ranking_declarations(&self, start: chrono::DateTime<chrono::Utc>) -> Result<Vec<RankingDeclaration>, RankingsError> {
        let start = time::OffsetDateTime::from_unix_timestamp(start.timestamp()).map_err(|error| RankingsError(error.to_string()))?;
        let rows = sqlx::query!(
            "SELECT m.parliament_member_id, m.name, m.party_id, m.party_name,
                d.source_declaration_id, d.category_id, d.category_name, d.registration_date,
                e.id AS \"entry_id?\", e.amount, NULLIF(btrim(e.currency, $2), '') AS currency,
                f.id AS \"funder_id?\", COALESCE(n.preferred_name, f.funder_name) AS funder_name, f.funder_kind
             FROM exposed.declarations d
             JOIN exposed.members m ON m.id = d.member_id
             LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
             LEFT JOIN exposed.funder_alias_groups g ON g.funder_id = e.funder_id
             LEFT JOIN exposed.funders f ON f.id = COALESCE(g.group_id, e.funder_id)
             LEFT JOIN exposed.funder_group_names n ON n.group_id = f.id
             WHERE d.registration_date >= $1
             ORDER BY d.source_declaration_id, e.id",
            start, CURRENCY_WHITESPACE
        ).fetch_all(self.pool()).await?;
        let mut declarations: Vec<RankingDeclaration> = Vec::new();
        for row in rows {
            if declarations.last().is_none_or(|source| source.declaration.source_id != row.source_declaration_id) {
                declarations.push(RankingDeclaration {
                    member: RankedMember { id: row.parliament_member_id.to_string().parse().map_err(|error: crate::domain::models::parliament_member::ParseMemberIdError| RankingsError(error.to_string()))?, name: row.name },
                    party: RankedParty { id: row.party_id, name: row.party_name },
                    declaration: MemberDeclaration { source_id: row.source_declaration_id, category: DeclarationCategory::from_source_id(row.category_id), category_name: row.category_name, registered_at: row.registration_date.map(|date| chrono::DateTime::from_timestamp(date.unix_timestamp(), date.nanosecond()).ok_or_else(|| RankingsError("Stored registration date is out of range".into()))).transpose()?, entries: Vec::new() },
                    funders: Vec::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row.funder_id.zip(row.funder_name).map(|(id, name)| {
                    let kind = row.funder_kind.as_deref().map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str).map_err(|error| RankingsError(error.to_string()))?;
                    Ok::<_, RankingsError>(RankedFunder { id: FunderId::new(id), name, kind })
                }).transpose()?;
                if let Some(source) = declarations.last_mut() {
                    source.declaration.entries.push(DeclaredFunding { funder: None, payment_type: None, amount: row.amount, currency: row.currency });
                    source.funders.push(funder);
                }
            }
        }
        Ok(declarations)
    }
}

