import { expect, test } from "./backend";
import { rankingFixture } from "./rankings-fixtures";

test("rankings SSR includes exact top ten and category switching is immediate and local", async ({
  page,
  backend,
  request,
  baseURL,
}) => {
  let reads = 0;
  await backend.route("**/api/rankings", async (route) => {
    reads += 1;
    await route.fulfill({ json: rankingFixture });
  });
  const ssr = await request.get(`${baseURL}/rankings`);
  const html = await ssr.text();
  expect(html).toContain("£9,007,199,254,740,993.123456789");
  expect(html).toContain("Member 10");
  await page.goto("/");
  await page.getByRole("link", { name: "Rankings", exact: true }).click();
  await expect(page.getByRole("heading", { level: 1 })).toHaveText("Rankings");
  const rows = page.getByRole("list", { name: "MPs rankings" });
  await expect(rows.getByRole("listitem")).toHaveCount(10);
  await expect(
    rows.getByRole("link", { name: "Member 1", exact: true }),
  ).toHaveAttribute("href", "/members/1");
  await expect(rows).toContainText("£9,007,199,254,740,993.123456789");
  await expect(rows).toContainText("Incomplete");
  await expect(rows).toContainText("Example Party · Example constituency");
  const before = reads;
  const individuals = page.getByRole("button", { name: "Individuals" });
  await individuals.focus();
  await page.keyboard.press("Space");
  await expect(individuals).toBeFocused();
  await expect(individuals).toHaveAttribute("aria-pressed", "true");
  await expect(individuals).toContainText("✓");
  await expect(
    page.getByRole("list", { name: "Individuals rankings" }),
  ).toContainText("£0.00");
  await expect(page.getByText("Donations and support · GBP")).toBeVisible();
  await page.getByRole("button", { name: "Companies" }).click();
  await expect(
    page.getByRole("link", { name: "Example company" }),
  ).toHaveAttribute("href", "/funders/10000000-0000-0000-0000-000000000002");
  await expect(
    page.getByRole("list", { name: "Companies rankings" }),
  ).toContainText("−£12.3456789");
  await page.getByRole("button", { name: "Parties" }).click();
  const parties = page.getByRole("list", { name: "Parties rankings" });
  await expect(parties).toContainText("Amount unavailable");
  await expect(parties.getByRole("link")).toHaveCount(0);
  await expect(
    page.getByText("Support declared by MPs, grouped by their latest party."),
  ).toBeVisible();
  expect(reads).toBe(before);
  await expect(
    page.getByRole("button", { name: /All records|Show more|Replay/u }),
  ).toHaveCount(0);
});

test("rankings fit narrow viewports and honor reduced motion", async ({
  page,
  backend,
}) => {
  await backend.route("**/api/rankings", async (route) =>
    route.fulfill({ json: rankingFixture }),
  );
  await page.setViewportSize({ width: 320, height: 900 });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/rankings");
  await expect(
    page.getByRole("list", { name: "MPs rankings" }).getByRole("listitem"),
  ).toHaveCount(10);
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(
    320,
  );
  const row = page.getByRole("listitem").first();
  await expect(row).toHaveCSS("animation-name", "none");
  await page.getByRole("button", { name: "Companies" }).click();
  await expect(page.getByRole("listitem").first()).toHaveCSS(
    "animation-name",
    "none",
  );
});

test("rankings report unavailable and empty snapshots", async ({
  page,
  backend,
}) => {
  await backend.route("**/api/rankings", async (route) =>
    route.fulfill({ status: 503 }),
  );
  await page.goto("/rankings");
  await expect(page.getByRole("alert")).toContainText(
    "Rankings couldn’t load. Try again.",
  );
  await backend.route("**/api/rankings", async (route) =>
    route.fulfill({ json: { ...rankingFixture, members: [] } }),
  );
  await page.reload();
  await expect(page.getByText("No declarations found.")).toBeVisible();
});
use crate::{
    domain::{
        models::funder::FunderId,
        services::{
            entity_details::{EntityDetailsService, Service as DetailsService},
            rankings::{RankingsService, Service},
        },
    },
    outbound::ExposedDatabase,
};
use sqlx::PgPool;

#[sqlx::test(migrations = "../db/migrations", fixtures("rankings"))]
async fn rankings_preserve_summary_parity_canonical_identity_and_party_attribution(pool: PgPool) {
    let db = ExposedDatabase::from(pool);
    let rankings = Service::new(db.clone()).rankings().await.unwrap();
    let details = DetailsService::new(db.clone());
    assert_eq!(rankings.members.len(), 6);
    for row in &rankings.members {
        let member = details
            .member(row.identity.id.value().to_string().parse().unwrap())
            .await
            .unwrap();
        let expected = member.summary.declared_totals.current_term;
        assert_eq!(row.total.amount, expected.amount);
        assert_eq!(row.total.declaration_count, expected.declaration_count);
        assert_eq!(row.total.incomplete, expected.incomplete);
    }
    let first = &rankings.members[0];
    assert_eq!(first.identity.id.value(), 1);
    assert_eq!(
        first.total.amount,
        Some("52.56913578246913578".parse().unwrap())
    );
    assert_eq!(first.total.declaration_count, 2);
    assert!(first.total.incomplete);
    assert_eq!(rankings.members[2].identity.id.value(), 6);
    assert_eq!(
        rankings.members[2].total.amount,
        Some("-1".parse().unwrap())
    );
    assert_eq!(rankings.members[3].identity.id.value(), 3);
    assert_eq!(rankings.members[3].total.amount, None);
    assert!(rankings.members[3].total.incomplete);
    assert_eq!(rankings.members[4].identity.id.value(), 4);
    assert_eq!(rankings.members[4].total.declaration_count, 1);
    assert!(!rankings.members[4].total.incomplete);
    assert_eq!(rankings.members[5].identity.id.value(), 5);
    assert!(!rankings.members[5].total.incomplete);
    assert_eq!(rankings.companies.len(), 1);
    let company = &rankings.companies[0];
    assert_eq!(
        company.identity.id,
        "10000000-0000-0000-0000-000000000001"
            .parse::<FunderId>()
            .unwrap()
    );
    assert_eq!(company.identity.name, "Preferred company");
    assert_eq!(
        company.total.amount,
        Some("2.56913578246913578".parse().unwrap())
    );
    assert_eq!(company.total.declaration_count, 2);
    assert!(company.total.incomplete);
    assert_eq!(rankings.individuals.len(), 2);
