    assert_eq!(
        company.total.amount,
        Some("2.56913578246913578".parse().unwrap())
    );
    assert_eq!(company.total.declaration_count, 2);
    assert!(company.total.incomplete);
    assert_eq!(rankings.individuals.len(), 2);
