{"status":"fulfilled","value":{"chunk_id":"9b84db","wall_time_seconds":0.000007875,"exit_code":0,"original_token_count":3182,"output":"<script lang="ts" generics="Id extends string">
  import Icon from "./Icon.svelte";
  import type { CategoryWheelOption } from "./ranking-types";
  let {
    options,
    selected,
    onselect,
    label,
    size = 284,
  }: {
    options: CategoryWheelOption<Id>[];
    selected: Id;
    onselect: (id: Id) => void;
    label: string;
    size?: number;
  } = $props();
  let focused = $state<Id | null>(null);
</script>

<div
  class="category-wheel"
  role="group"
  aria-label={label}
  style:width={`${size}px`}
  style:height={`${size}px`}
>
  <div class="wheel-canvas" style:transform={`scale(${size / 284})`}>
    <svg viewBox="0 0 284 284" aria-hidden="true">
      {#each options as option}
        {#if option.id === focused}<path
            class="focus-outline"
            d={option.path}
            transform={`translate(${option.left} ${option.top})`}
          />{/if}
        <path
          d={option.path}
          transform={`translate(${option.left} ${option.top})`}
          class:selected={option.id === selected}
          data-accent={option.accent}
        />
      {/each}
    </svg>
    {#each options as option}
      <button
        type="button"
        aria-pressed={selected === option.id}
        onclick={() => onselect(option.id)}
        onfocus={(event) =>
          (focused = event.currentTarget.matches(":focus-visible")
            ? option.id
            : null)}
        onblur={() => (focused = null)}
        data-accent={option.accent}
        style:left={`${option.left}px`}
        style:top={`${option.top}px`}
        style:clip-path={`path('${option.path}')`}
      >
        <span
          class="sector-label"
          style:left={`${option.x}px`}
          style:top={`${option.y}px`}
        >
          <Icon name={option.icon} size={20} />
          <span>{option.label}</span>
          <span class="selection-mark" aria-hidden="true"
            >{selected === option.id ? "✓" : ""}</span
          >
        </span>
      </button>
    {/each}
  </div>
</div>

<style>
  .category-wheel {
    position: relative;
    aspect-ratio: 1;
    flex: none;
  }
  .wheel-canvas {
    position: relative;
    width: 284px;
    height: 284px;
    transform-origin: top left;
  }
  svg {
    display: block;
    width: 284px;
    height: 284px;
    overflow: visible;
    pointer-events: none;
  }
  path {
    fill: var(--surface);
    stroke: var(--line);
    stroke-width: 1.5;
    transition:
