          </p>{/if}
        <RankingList
          {rows}
          label={`${rankingCategories.find((category) => category.id === selected)?.label} rankings`}
        />
        {#if rows.length === 0}<p class="empty">No declarations found.</p>{/if}
      </div>
    {:else}<h1>Rankings</h1>
      <Notice role="alert">{data.error}</Notice>{/if}
  </main>
</AppShell>

<style>
