    path: "M138 8 A130 130 0 0 0 8 138 L78 138 A60 60 0 0 1 138 78 Z",
    left: 0,
    top: 0,
    x: 73,
    y: 73,
  },
  {
    id: "individuals",
    label: "Individuals",
    icon: "person",
    accent: "funder",
    path: "M4 8 A130 130 0 0 1 134 138 L64 138 A60 60 0 0 0 4 78 Z",
    left: 142,
    top: 0,
    x: 69,
    y: 73,
  },
  {
    id: "companies",
    label: "Companies",
    icon: "building",
    accent: "funder",
    path: "M8 4 A130 130 0 0 0 138 134 L138 64 A60 60 0 0 1 78 4 Z",
    left: 0,
    top: 142,
    x: 73,
    y: 69,
  },
  {
    id: "parties",
    label: "Parties",
    icon: "group",
    accent: "neutral",
    path: "M4 134 A130 130 0 0 0 134 4 L64 4 A60 60 0 0 1 4 64 Z",
    left: 142,
    top: 142,
    x: 69,
    y: 69,
  },
] satisfies CategoryWheelOption<RankingCategory>[];

export function rankingRows(
  rankings: Rankings,
  category: RankingCategory,
): RankingRow[] {
  const entries = rankings[category];
  const bars = categoryBars(
    entries.map(({ total }) => ({ amount: total.amount })),
    "maximum",
  );
  return entries.map((entry, index) => ({
    key: `${category}:${entry.id}`,
    name: entry.name,
    context:
      entry.context ??
      `${entry.total.declarationCount} declaration${entry.total.declarationCount === 1 ? "" : "s"}`,
    href:
      category === "parties"
        ? undefined
        : `/${category === "members" ? "members" : "funders"}/${entry.id}`,
    amount: formatPounds(entry.total.amount),
    incomplete: entry.total.incomplete,
    width: bars[index].width,
    negative: bars[index].negative,
    accent:
      category === "members"
        ? "member"
        : category === "parties"
          ? "neutral"
          : "funder",
  }));
}
