import type { IconName } from "./icon-types";
export type EntityAccent = "member" | "funder" | "neutral";
export interface CategoryWheelOption<Id extends string = string> {
  id: Id;
  label: string;
  icon: IconName;
  accent: EntityAccent;
  path: string;
  left: number;
  top: number;
  x: number;
  y: number;
}
export interface RankingRow {
  key: string;
  name: string;
  context: string;
  href?: string;
  amount: string;
  incomplete: boolean;
  width: number;
  negative: boolean;
  accent: EntityAccent;
}
import { categoryBars } from "./entity-details";
import { formatPounds } from "./member-summary";
import type { DeclaredGbpPeriodTotal } from "./entity-details";
import type { CategoryWheelOption, RankingRow } from "./ui";

export type RankingCategory =
  "members" | "individuals" | "companies" | "parties";
export interface RankingEntry {
  id: string;
  name: string;
  context: string | null;
  total: DeclaredGbpPeriodTotal;
}
export interface Rankings {
  currentTermStart: string;
  members: RankingEntry[];
  individuals: RankingEntry[];
  companies: RankingEntry[];
  parties: RankingEntry[];
}
export const rankingCategories = [
  {
    id: "members",
    label: "MPs",
    icon: "parliament",
    accent: "member",
    path: "M138 8 A130 130 0 0 0 8 138 L78 138 A60 60 0 0 1 138 78 Z",
    left: 0,
    top: 0,
    x: 73,
    y: 73,
